-- Rebuild Medina Book 3 lesson 11 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 43-48.
-- Three Qur'anic strings hidden by DOC control characters were transcribed literally from visible PDF pages 44-45.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11';
  if old_rule_count <> 5 then raise exception 'Expected 5 generated Book 3 lesson 11 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '11', 'الْمُبْتَدَأُ وَالْخَبَرُ وَأَنْوَاعُ الْمُبْتَدَأِ (мубтада, хабар и виды мубтада)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-subject">الْمُبْتَدَأُ</span> هُوَ الِاسْمُ الْمَرْفُوعُ الَّذِي نَتَحَدَّثُ عَنْهُ، وَ<span class="ar-tone-predicate">الْخَبَرُ</span> هُوَ الِاسْمُ الْمَرْفُوعُ الَّذِي تَتِمُّ بِهِ الْفَائِدَةُ.</span><p class="rule-study-text">Мубтада — имя в именительном падеже, о котором сообщается; хабар — поднятый компонент, которым завершается полезный смысл.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Как определить мубтада и хабар</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-table-ru">то, о чём говорится</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">сообщение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكِتَابُ جَدِيدٌ.</span><span class="rule-table-ru">Книга новая.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْكِتَابُ</span><span class="rule-table-ru">книга</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">جَدِيدٌ</span><span class="rule-table-ru">новая</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَتَحَدَّثُ عَنِ الْكِتَابِ، وَتَتِمُّ الْفَائِدَةُ بِكَلِمَةِ جَدِيدٌ</span><span class="rule-table-ru">говорим о книге; слово «новая» завершает смысл</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقُرْآنُ كِتَابُ اللَّهِ.</span><span class="rule-table-ru">Коран — Книга Аллаха.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْقُرْآنُ</span><span class="rule-table-ru">Коран</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">كِتَابُ اللَّهِ</span><span class="rule-table-ru">Книга Аллаха</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةٌ اسْمِيَّةٌ</span><span class="rule-table-ru">именное предложение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتَ طَالِبٌ.</span><span class="rule-table-ru">Ты студент.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْتَ</span><span class="rule-table-ru">ты</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">طَالِبٌ</span><span class="rule-table-ru">студент</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةٌ اسْمِيَّةٌ</span><span class="rule-table-ru">именное предложение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا مَسْجِدٌ.</span><span class="rule-table-ru">Это мечеть.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">هَذَا</span><span class="rule-table-ru">это</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَسْجِدٌ</span><span class="rule-table-ru">мечеть</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةٌ اسْمِيَّةٌ</span><span class="rule-table-ru">именное предложение</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два вида мубтада</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْمُبْتَدَأِ</span><span class="rule-table-ru">вид мубтада</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمٌ صَرِيحٌ</span><span class="rule-table-ru">явно выраженное имя</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اللَّهُ رَبُّنَا. مُحَمَّدٌ رَسُولُنَا. الْإِسْلَامُ دِينُنَا. نَحْنُ طُلَّابٌ. هُنَّ طَالِبَاتٌ.</span><span class="rule-table-ru">Аллах — наш Господь. Мухаммад — наш посланник. Ислам — наша религия. Мы студенты. Они студентки.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَصْدَرٌ مُؤَوَّلٌ</span><span class="rule-table-ru">истолковываемый масдар</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْ تَكْتُبَ الدَّرْسَ أَفْضَلُ مِنَ اللَّعِبِ.</span><span class="rule-table-ru">Написать урок лучше, чем играть.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Истолкование масдара</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الْمُؤَوَّلُ</span><span class="rule-table-ru">конструкция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الصَّرِيحُ</span><span class="rule-table-ru">явный масдар</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْ تَكْتُبَ الدَّرْسَ أَفْضَلُ مِنَ اللَّعِبِ.</span><span class="rule-table-ru">Написать урок лучше, чем играть.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">كِتَابَتُكَ الدَّرْسَ أَفْضَلُ مِنَ اللَّعِبِ.</span><span class="rule-table-ru">Написание тобой урока лучше игры.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْ تَكْتُبَ</span><span class="rule-table-ru">то, что ты пишешь; твоё написание</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">﴿ وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى ﴾</span><span class="rule-table-ru">«А простить — ближе к богобоязненности»</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَفْوُكُمْ أَقْرَبُ لِلتَّقْوَى.</span><span class="rule-table-ru">Ваше прощение ближе к богобоязненности.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْ تَعْفُوا</span><span class="rule-table-ru">то, что вы простите; ваше прощение</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Мубтада — поднятое имя, о котором говорится; хабар — поднятый компонент, завершающий смысл. Мубтада бывает явным именем или истолковываемым масдаром.', 'الْمُبْتَدَأُ هُوَ الِاسْمُ الْمَرْفُوعُ الَّذِي نَتَحَدَّثُ عَنْهُ، وَالْخَبَرُ هُوَ الِاسْمُ الْمَرْفُوعُ الَّذِي تَتِمُّ بِهِ الْفَائِدَةُ. وَالْمُبْتَدَأُ نَوْعَانِ: اسْمٌ صَرِيحٌ وَمَصْدَرٌ مُؤَوَّلٌ.'),
    ('Мединский курс (Том 3)', '11', 'تَعْرِيفُ الْمُبْتَدَأِ وَتَنْكِيرُهُ (определённость и неопределённость мубтада)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَصْلُ فِي <span class="ar-tone-subject">الْمُبْتَدَأِ</span> أَنْ يَكُونَ مَعْرِفَةً، وَيَأْتِي نَكِرَةً بِشُرُوطٍ.</span><p class="rule-study-text">Обычно мубтада является определённым. Шарх приводит два условия, при которых оно может быть неопределённым.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Определённое мубтада</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ الْمَعْرِفَةُ</span><span class="rule-table-ru">определённое мубтада</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّهُ رَبُّنَا.</span><span class="rule-table-ru">Аллах — наш Господь.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اللَّهُ</span><span class="rule-table-ru">Аллах</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَحْنُ طُلَّابٌ.</span><span class="rule-table-ru">Мы студенты.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نَحْنُ</span><span class="rule-table-ru">мы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَا مُدَرِّسٌ.</span><span class="rule-table-ru">Я преподаватель.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنَا</span><span class="rule-table-ru">я</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِفْتَاحُ الْجَنَّةِ الصَّلَاةُ.</span><span class="rule-table-ru">Ключ Рая — молитва.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مِفْتَاحُ الْجَنَّةِ</span><span class="rule-table-ru">ключ Рая</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Неопределённое мубтада после предшествующего хабар</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَبَرُ الْمُقَدَّمُ</span><span class="rule-table-ru">предшествующий хабар</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ النَّكِرَةُ</span><span class="rule-table-ru">неопределённое мубтада</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِي أَخٌ.</span><span class="rule-table-ru">У меня есть брат.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لِي</span><span class="rule-table-ru">у меня</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَخٌ</span><span class="rule-table-ru">брат</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فِي الْبَيْتِ ضَيْفٌ.</span><span class="rule-table-ru">В доме гость.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">فِي الْبَيْتِ</span><span class="rule-table-ru">в доме</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَيْفٌ</span><span class="rule-table-ru">гость</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عِنْدَنَا سَيَّارَةٌ.</span><span class="rule-table-ru">У нас есть машина.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عِنْدَنَا</span><span class="rule-table-ru">у нас</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">سَيَّارَةٌ</span><span class="rule-table-ru">машина</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَوْقَ الشَّجَرَةِ عُصْفُورٌ.</span><span class="rule-table-ru">Над деревом птица.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">فَوْقَ الشَّجَرَةِ</span><span class="rule-table-ru">над деревом</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عُصْفُورٌ</span><span class="rule-table-ru">птица</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Вопросительное имя как неопределённое мубтада</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-table-ru">мубтада</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">хабар</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا بِكَ؟</span><span class="rule-table-ru">Что с тобой?</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">что; в синтаксическом месте именительного падежа как мубтада</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">بِكَ</span><span class="rule-table-ru">с тобой</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ مَرِيضٌ؟</span><span class="rule-table-ru">Кто болен?</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَنْ</span><span class="rule-table-ru">кто; в синтаксическом месте именительного падежа как мубтада</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَرِيضٌ</span><span class="rule-table-ru">болен</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَمْ طَالِبًا فِي الْفَصْلِ؟</span><span class="rule-table-ru">Сколько студентов в классе?</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">كَمْ</span><span class="rule-table-ru">сколько; в синтаксическом месте именительного падежа как мубтада</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">فِي الْفَصْلِ</span><span class="rule-table-ru">в классе</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Грамматическое положение вопросительных имён</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">أَسْمَاءُ الِاسْتِفْهَامِ مَا وَمَنْ وَكَمْ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ، وَهِيَ نَكِرَاتٌ.</span><p class="rule-study-text">В этих примерах вопросительные имена находятся в синтаксическом месте именительного падежа как мубтада и являются неопределёнными.</p></div></div>', 2, 'rule', 'По общему правилу мубтада определённое; неопределённое мубтада допускается после предшествующего شِبْهُ جُمْلَةٍ либо когда оно является вопросительным именем.', 'الْأَصْلُ فِي الْمُبْتَدَأِ أَنْ يَكُونَ مَعْرِفَةً. وَيَأْتِي نَكِرَةً إِذَا تَقَدَّمَ عَلَيْهِ خَبَرٌ شِبْهُ جُمْلَةٍ، أَوْ إِذَا كَانَ اسْمَ اسْتِفْهَامٍ.'),
    ('Мединский курс (Том 3)', '11', 'التَّرْتِيبُ بَيْنَ الْمُبْتَدَأِ وَالْخَبَرِ (порядок мубтада и хабар)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَصْلُ أَنْ يَتَقَدَّمَ <span class="ar-tone-subject">الْمُبْتَدَأُ</span> عَلَى <span class="ar-tone-predicate">الْخَبَرِ</span>.</span><p class="rule-study-text">По общему правилу мубтада стоит перед хабаром.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Обычный порядок</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-table-ru">мубтада</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">хабар</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتَ مُدَرِّسٌ.</span><span class="rule-table-ru">Ты преподаватель.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْتَ</span><span class="rule-table-ru">ты</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُدَرِّسٌ</span><span class="rule-table-ru">преподаватель</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقُرْآنُ كِتَابُ اللَّهِ.</span><span class="rule-table-ru">Коран — Книга Аллаха.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْقُرْآنُ</span><span class="rule-table-ru">Коран</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">كِتَابُ اللَّهِ</span><span class="rule-table-ru">Книга Аллаха</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْ تَحْفَظَ الْقُرْآنَ خَيْرٌ لَكَ.</span><span class="rule-table-ru">Выучить Коран лучше для тебя.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْ تَحْفَظَ الْقُرْآنَ</span><span class="rule-table-ru">истолковываемый масдар</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَيْرٌ لَكَ</span><span class="rule-table-ru">лучше для тебя</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Обязательное предшествование мубтада</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْطُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">إِذَا كَانَ الْمُبْتَدَأُ اسْمَ اسْتِفْهَامٍ؛ لِأَسْمَاءِ الِاسْتِفْهَامِ حَقُّ الصَّدَارَةِ</span><span class="rule-table-ru">если мубтада является вопросительным именем; вопросительные имена должны стоять в начале</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَا بِكَ؟ مَنْ مَرِيضٌ؟ كَمْ كِتَابًا عِنْدَكَ؟</span><span class="rule-table-ru">Что с тобой? Кто болен? Сколько книг у тебя?</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">إِذَا كَانَ الْمُبْتَدَأُ وَالْخَبَرُ مَعْرِفَتَيْنِ</span><span class="rule-table-ru">если и мубтада, и хабар определённые</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْكِتَابُ صَدِيقِي. رَبُّنَا خَالِقُنَا.</span><span class="rule-table-ru">Книга — мой друг. Наш Господь — наш Создатель.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا كَانَ الْخَبَرُ جُمْلَةً فِعْلِيَّةً</span><span class="rule-table-ru">если хабар является глагольным предложением</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الطَّالِبُ يَكْتُبُ. فَاطِمَةُ خَرَجَتْ.</span><span class="rule-table-ru">Студент пишет. Фатима вышла.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Обязательное предшествование хабара</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْطُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا كَانَ الْخَبَرُ اسْمَ اسْتِفْهَامٍ</span><span class="rule-table-ru">если хабар является вопросительным именем</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَا اسْمُكَ؟ كَيْفَ حَالُكَ؟ مَنِ الْمَرِيضُ؟</span><span class="rule-table-ru">Как тебя зовут? Как твоё состояние? Кто болен?</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا كَانَ الْخَبَرُ شِبْهَ جُمْلَةٍ وَالْمُبْتَدَأُ نَكِرَةً</span><span class="rule-table-ru">если хабар — شِبْهُ جُمْلَةٍ, а мубтада — неопределённое</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَدَيَّ سَيَّارَةٌ. فِي الْبَيْتِ ضَيْفٌ.</span><span class="rule-table-ru">У меня машина. В доме гость.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">شَاهِدٌ قُرْآنِيٌّ</span><span class="rule-table-ru">коранический пример</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">﴿ وَلَدَيْنَا مَزِيدٌ ﴾</span><span class="rule-table-ru">«И у Нас есть ещё»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">شَاهِدٌ قُرْآنِيٌّ</span><span class="rule-table-ru">коранический пример</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">﴿ وَعَلَى أَبْصَارِهِمْ غِشَاوَةٌ ﴾</span><span class="rule-table-ru">«И на их взорах — завеса»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Почему вопросительное имя здесь является хабаром</span><span class="rule-main-ar ar-tone-predicate" dir="rtl" lang="ar">وَقَعَ اسْمُ الِاسْتِفْهَامِ هُنَا خَبَرًا؛ لِأَنَّهُ نَكِرَةٌ وَمَا بَعْدَهُ مَعْرِفَةٌ، وَحَقُّ الْمُبْتَدَأِ أَنْ يَكُونَ مَعْرِفَةً.</span><p class="rule-study-text">В этих вопросах вопросительное имя выступает хабаром: оно неопределённое, а следующее за ним слово — определённое и поэтому является мубтада.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Допустимое предшествование хабара</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْطُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا لَمْ يَحْصُلْ بِتَقْدِيمِهِ لَبْسٌ وَإِشْكَالٌ</span><span class="rule-table-ru">если перенос не вызывает двусмысленности и затруднения</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عَجِيبٌ كَلَامُهُ. قَائِمٌ عَمْرٌو.</span><span class="rule-table-ru">Удивительна его речь. Амр стоит.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا كَانَ الْخَبَرُ شِبْهَ جُمْلَةٍ وَالْمُبْتَدَأُ مَعْرِفَةً</span><span class="rule-table-ru">если хабар — شِبْهُ جُمْلَةٍ, а мубтада — определённое</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عِنْدَنَا زَيْدٌ. فِي صُدُورِنَا كِتَابُ اللَّهِ.</span><span class="rule-table-ru">У нас Зайд. В наших сердцах — Книга Аллаха.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا كَانَ الْخَبَرُ اسْمَ فَاعِلٍ مَسْبُوقًا بِاسْتِفْهَامٍ</span><span class="rule-table-ru">если хабар — имя действующего лица после вопросительной хамзы</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">أَمُدَرِّسٌ أَنْتَ؟ أَمُسَافِرٌ أَخُوكَ؟</span><span class="rule-table-ru">Преподаватель ли ты? Путешественник ли твой брат?</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'Обычный порядок — мубтада перед хабаром; шарх перечисляет случаи обязательного сохранения мубтада первым, обязательного вынесения хабара и допустимого вынесения хабара.', 'الْأَصْلُ أَنْ يَتَقَدَّمَ الْمُبْتَدَأُ عَلَى الْخَبَرِ. وَيَجِبُ تَقْدِيمُ الْمُبْتَدَأِ فِي مَوَاضِعَ، وَيَجِبُ تَقْدِيمُ الْخَبَرِ فِي مَوَاضِعَ أُخْرَى، وَيَجُوزُ تَقْدِيمُ الْخَبَرِ إِذَا أَمِنَ اللَّبْسُ أَوْ تَحَقَّقَ شَرْطٌ مِنَ الشُّرُوطِ الْمَذْكُورَةِ.'),
    ('Мединский курс (Том 3)', '11', 'حَذْفُ الْمُبْتَدَأِ أَوِ الْخَبَرِ (опущение мубтада или хабара)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يَجُوزُ حَذْفُ <span class="ar-tone-subject">الْمُبْتَدَأِ</span> أَوْ <span class="ar-tone-predicate">الْخَبَرِ</span> أَوْ حَذْفُهُمَا مَعًا إِذَا عُلِمَ الْمَحْذُوفُ مِنَ السِّيَاقِ.</span><p class="rule-study-text">Компонент именного предложения можно не произносить, когда собеседнику понятно, что именно подразумевается.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все случаи из шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَحْذُوفُ</span><span class="rule-table-ru">что опущено</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السُّؤَالُ</span><span class="rule-table-ru">вопрос</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَوَابُ</span><span class="rule-table-ru">краткий ответ</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّقْدِيرُ الْكَامِلُ</span><span class="rule-table-ru">полная подразумеваемая форма</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-table-ru">мубтада</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَيْفَ حَالُكَ؟</span><span class="rule-table-ru">Как ты?</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بِخَيْرٍ.</span><span class="rule-table-ru">Хорошо.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَا بِخَيْرٍ.</span><span class="rule-table-ru">Я в порядке.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-table-ru">мубтада</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا اسْمُكَ؟</span><span class="rule-table-ru">Как тебя зовут?</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَامِدٌ.</span><span class="rule-table-ru">Хамид.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمِي حَامِدٌ.</span><span class="rule-table-ru">Меня зовут Хамид.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">хабар</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَمْ كِتَابًا عِنْدَكَ؟</span><span class="rule-table-ru">Сколько книг у тебя?</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابَانِ.</span><span class="rule-table-ru">Две книги.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عِنْدِي كِتَابَانِ.</span><span class="rule-table-ru">У меня две книги.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">хабар</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ فَاهِمٌ؟</span><span class="rule-table-ru">Кто понимает?</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَا.</span><span class="rule-table-ru">Я.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَا فَاهِمٌ.</span><span class="rule-table-ru">Я понимаю.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ وَالْخَبَرُ</span><span class="rule-table-ru">оба компонента</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَطَالِبٌ أَنْتَ؟</span><span class="rule-table-ru">Ты студент?</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَعَمْ.</span><span class="rule-table-ru">Да.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَعَمْ، أَنَا طَالِبٌ.</span><span class="rule-table-ru">Да, я студент.</span></td></tr></tbody></table></div></div></div>', 4, 'rule', 'Мубтада, хабар или оба компонента могут быть опущены, если их легко восстановить из вопроса и контекста.', 'يَجُوزُ حَذْفُ الْمُبْتَدَأِ إِذَا عُلِمَ، وَيَجُوزُ حَذْفُ الْخَبَرِ إِذَا عُلِمَ، وَيَجُوزُ حَذْفُهُمَا مَعًا إِذَا عُلِمَا مِنَ السِّيَاقِ.'),
    ('Мединский курс (Том 3)', '11', 'أَنْوَاعُ الْخَبَرِ (виды хабара)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-predicate">الْخَبَرُ</span> ثَلَاثَةُ أَنْوَاعٍ: مُفْرَدٌ، وَجُمْلَةٌ، وَشِبْهُ جُمْلَةٍ.</span><p class="rule-study-text">Хабар делится на одиночный, предложение и شِبْهُ جُمْلَةٍ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Одиночный хабар</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَبَرُ الْمُفْرَدُ</span><span class="rule-table-ru">одиночный хабар</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ.</span><span class="rule-table-ru">Студент усерден.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُجْتَهِدٌ</span><span class="rule-table-ru">усердный</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطَّالِبَانِ مُجْتَهِدَانِ.</span><span class="rule-table-ru">Два студента усердны.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُجْتَهِدَانِ</span><span class="rule-table-ru">двое усердны</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطُّلَّابُ مُجْتَهِدُونَ.</span><span class="rule-table-ru">Студенты усердны.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُجْتَهِدُونَ</span><span class="rule-table-ru">усердны</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطَّالِبَاتُ مُجْتَهِدَاتٌ.</span><span class="rule-table-ru">Студентки усердны.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُجْتَهِدَاتٌ</span><span class="rule-table-ru">усердны</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Значение термина</span><span class="rule-main-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَقْصُودُ بِالْخَبَرِ الْمُفْرَدِ مَا لَيْسَ جُمْلَةً وَلَا شِبْهَ جُمْلَةٍ.</span><p class="rule-study-text">Здесь «одиночный» означает: хабар не является ни предложением, ни شِبْهُ جُمْلَةٍ; его грамматическое число может быть любым.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Хабар — предложение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْجُمْلَةِ</span><span class="rule-table-ru">вид предложения</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الضَّمِيرُ الرَّابِطُ</span><span class="rule-table-ru">местоименная связь с мубтада</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">جُمْلَةٌ اسْمِيَّةٌ</span><span class="rule-table-ru">именное предложение</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُدِيرُ مَا اسْمُهُ؟ النِّيَّةُ مَحَلُّهَا الْقَلْبُ. الطَّالِبُ كِتَابُهُ جَدِيدٌ.</span><span class="rule-table-ru">Директор — как его зовут? Намерение — его место сердце. У студента его книга новая.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْهَاءُ فِي اسْمُهُ وَمَحَلُّهَا وَكِتَابُهُ</span><span class="rule-table-ru">местоимение «его/её» в трёх примерах</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جُمْلَةٌ فِعْلِيَّةٌ</span><span class="rule-table-ru">глагольное предложение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اللَّهُ خَلَقَنَا. الْمُدَرِّسَانِ خَرَجَا. الطُّلَّابُ يَكْتُبُونَ دُرُوسَهُمْ.</span><span class="rule-table-ru">Аллах создал нас. Два преподавателя вышли. Студенты пишут свои уроки.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمِيرُ الْمُسْتَتِرُ، وَأَلِفُ الِاثْنَيْنِ، وَوَاوُ الْجَمَاعَةِ</span><span class="rule-table-ru">скрытое местоимение, алиф двойственного числа и вау группы</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Условие для хабара-предложения</span><span class="rule-main-ar ar-tone-predicate" dir="rtl" lang="ar">يُشْتَرَطُ فِي الْخَبَرِ الْجُمْلَةِ أَنْ يَشْتَمِلَ عَلَى ضَمِيرٍ يَعُودُ إِلَى الْمُبْتَدَأِ.</span><p class="rule-study-text">В предложении, выступающем хабаром, должно быть местоимение, возвращающееся к мубтада.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Хабар — شِبْهُ جُمْلَةٍ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ شِبْهِ الْجُمْلَةِ</span><span class="rule-table-ru">вид شِبْهُ جُمْلَةٍ</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">جَارٌّ وَمَجْرُورٌ</span><span class="rule-table-ru">предлог и имя в родительном падеже</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْحَمْدُ لِلَّهِ. الطُّلَّابُ فِي الْمَطْعَمِ.</span><span class="rule-table-ru">Хвала Аллаху. Студенты в столовой.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ظَرْفٌ</span><span class="rule-table-ru">обстоятельство места</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَنَّةُ تَحْتَ ظِلَالِ السُّيُوفِ. الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</span><span class="rule-table-ru">Рай — под тенями мечей. Преподаватель у директора.</span></td></tr></tbody></table></div></div></div>', 5, 'rule', 'Хабар бывает одиночным, предложением или شِبْهُ جُمْلَةٍ; хабар-предложение должно содержать местоименную связь с мубтада.', 'الْخَبَرُ ثَلَاثَةُ أَنْوَاعٍ: مُفْرَدٌ، وَجُمْلَةٌ، وَشِبْهُ جُمْلَةٍ. الْمُفْرَدُ مَا لَيْسَ جُمْلَةً وَلَا شِبْهَ جُمْلَةٍ. وَالْجُمْلَةُ اسْمِيَّةٌ أَوْ فِعْلِيَّةٌ، وَيُشْتَرَطُ فِيهَا ضَمِيرٌ يَعُودُ إِلَى الْمُبْتَدَأِ. وَشِبْهُ الْجُمْلَةِ جَارٌّ وَمَجْرُورٌ أَوْ ظَرْفٌ.'),
    ('Мединский курс (Том 3)', '11', 'إِعْرَابُ الْمُبْتَدَأِ وَالْخَبَرِ (грамматический разбор мубтада и хабара)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-subject">الْمُبْتَدَأُ</span> وَ<span class="ar-tone-predicate">الْخَبَرُ</span> مَرْفُوعَانِ، وَالْجُمْلَةُ أَوْ شِبْهُ الْجُمْلَةِ الْوَاقِعَةُ خَبَرًا تَكُونُ فِي مَحَلِّ رَفْعٍ.</span><p class="rule-study-text">Мубтада и одиночный хабар стоят в именительном падеже. Если хабар выражен предложением или شِبْهُ جُمْلَةٍ, вся конструкция находится в синтаксическом месте именительного падежа.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор: الطَّالِبُ مُجْتَهِدٌ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الطَّالِبُ</span><span class="rule-table-ru">студент</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ</span><span class="rule-table-ru">мубтада в именительном падеже; признак — явно выраженная дамма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ.</span><span class="rule-table-ru">Студент усерден.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُجْتَهِدٌ</span><span class="rule-table-ru">усердный</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ</span><span class="rule-table-ru">хабар в именительном падеже; признак — явно выраженная дамма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ مُفْرَدٌ</span><span class="rule-table-ru">одиночный хабар</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор: الْمُدِيرُ مَا اسْمُهُ؟</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ أَوِ الْجُمْلَةُ</span><span class="rule-table-ru">слово или конструкция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُدِيرُ</span><span class="rule-table-ru">директор</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ</span><span class="rule-table-ru">мубтада в именительном падеже; признак — явно выраженная дамма</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُبْتَدَأُ الْأَوَّلُ</span><span class="rule-table-ru">первое мубтада</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">что; как</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">اسْمُ اسْتِفْهَامٍ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ خَبَرٌ مُقَدَّمٌ</span><span class="rule-table-ru">вопросительное имя, построенное на сукуне; в синтаксическом месте именительного падежа как предшествующий хабар</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ مُقَدَّمٌ</span><span class="rule-table-ru">предшествующий хабар</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُهُ</span><span class="rule-table-ru">его имя</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ مُؤَخَّرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ، وَالضَّمِيرُ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru">отложенное мубтада в именительном падеже; признак — явно выраженная дамма; оно первый член идафы, а местоимение находится в синтаксическом месте родительного падежа как второй член</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ مُؤَخَّرٌ</span><span class="rule-table-ru">отложенное мубтада</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا اسْمُهُ؟</span><span class="rule-table-ru">как его имя?</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْجُمْلَةُ الِاسْمِيَّةُ مِنَ الْخَبَرِ وَالْمُبْتَدَأِ فِي مَحَلِّ رَفْعٍ خَبَرٌ لِلْمُبْتَدَأِ الْأَوَّلِ «الْمُدِيرُ»</span><span class="rule-table-ru">именное предложение из хабара и мубтада находится в синтаксическом месте именительного падежа как хабар первого мубтада «директор»</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ الْمُبْتَدَأِ الْأَوَّلِ</span><span class="rule-table-ru">хабар первого мубтада</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор: اللَّهُ خَلَقَنَا</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ أَوِ الْجُمْلَةُ</span><span class="rule-table-ru">слово или конструкция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اللَّهُ</span><span class="rule-table-ru">Аллах</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ</span><span class="rule-table-ru">мубтада в именительном падеже; признак — явно выраженная дамма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّهُ خَلَقَنَا.</span><span class="rule-table-ru">Аллах создал нас.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خَلَقَنَا</span><span class="rule-table-ru">создал нас</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى الْفَتْحِ، وَالضَّمِيرُ نَا فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ</span><span class="rule-table-ru">глагол прошедшего времени, построенный на фатхе; местоимение «нас» находится в синтаксическом месте винительного падежа как прямое дополнение; подлежащее — скрытое «он»</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْفَاعِلُ: هُوَ</span><span class="rule-table-ru">подразумеваемое подлежащее: он</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خَلَقَنَا</span><span class="rule-table-ru">глагольное предложение</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْجُمْلَةُ الْفِعْلِيَّةُ فِي مَحَلِّ رَفْعٍ خَبَرُ الْمُبْتَدَأِ</span><span class="rule-table-ru">глагольное предложение находится в синтаксическом месте именительного падежа как хабар мубтада</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ جُمْلَةٌ فِعْلِيَّةٌ</span><span class="rule-table-ru">хабар — глагольное предложение</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор: الْحَمْدُ لِلَّهِ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ أَوِ التَّرْكِيبُ</span><span class="rule-table-ru">слово или сочетание</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْحَمْدُ</span><span class="rule-table-ru">хвала</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ</span><span class="rule-table-ru">мубтада в именительном падеже; признак — явно выраженная дамма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَمْدُ لِلَّهِ.</span><span class="rule-table-ru">Хвала Аллаху.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">لِلَّهِ</span><span class="rule-table-ru">Аллаху</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">اللَّامُ حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْكَسْرِ، وَلَفْظُ الْجَلَالَةِ اسْمٌ مَجْرُورٌ بِاللَّامِ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ</span><span class="rule-table-ru">лам — предлог, построенный на касре; имя Аллаха стоит в родительном падеже после лама, признак — явно выраженная касра</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">جَارٌّ وَمَجْرُورٌ</span><span class="rule-table-ru">предлог и имя в родительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لِلَّهِ</span><span class="rule-table-ru">сочетание</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْجَارُّ وَالْمَجْرُورُ فِي مَحَلِّ رَفْعٍ خَبَرُ الْمُبْتَدَأِ</span><span class="rule-table-ru">предложное сочетание находится в синтаксическом месте именительного падежа как хабар мубтада</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ شِبْهُ جُمْلَةٍ</span><span class="rule-table-ru">хабар — شِبْهُ جُمْلَةٍ</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор: الْمُدَرِّسُ عِنْدَ الْمُدِيرِ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ أَوِ التَّرْكِيبُ</span><span class="rule-table-ru">слово или сочетание</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُدَرِّسُ</span><span class="rule-table-ru">преподаватель</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ</span><span class="rule-table-ru">мубтада в именительном падеже; признак — явно выраженная дамма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</span><span class="rule-table-ru">Преподаватель у директора.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عِنْدَ</span><span class="rule-table-ru">у; при</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفُ مَكَانٍ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ</span><span class="rule-table-ru">обстоятельство места в винительном падеже; признак — явно выраженная фатха; первый член идафы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ظَرْفُ مَكَانٍ</span><span class="rule-table-ru">обстоятельство места</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْمُدِيرِ</span><span class="rule-table-ru">директора</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ</span><span class="rule-table-ru">второй член идафы в родительном падеже; признак — явно выраженная касра</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru">второй член идафы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عِنْدَ الْمُدِيرِ</span><span class="rule-table-ru">у директора</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الظَّرْفُ مَعَ مَجْرُورِهِ فِي مَحَلِّ رَفْعٍ خَبَرُ الْمُبْتَدَأِ</span><span class="rule-table-ru">обстоятельство со своим зависимым именем находится в синтаксическом месте именительного падежа как хабар мубтада</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ شِبْهُ جُمْلَةٍ</span><span class="rule-table-ru">хабар — شِبْهُ جُمْلَةٍ</span></td></tr></tbody></table></div></div></div>', 6, 'rule', 'Шарх полностью разбирает одиночный, именной, глагольный и два вида شِبْهُ جُمْلَةٍ хабара; каждый внутренний компонент получает собственный разбор.', 'الْمُبْتَدَأُ وَالْخَبَرُ مَرْفُوعَانِ. وَإِذَا كَانَ الْخَبَرُ جُمْلَةً أَوْ شِبْهَ جُمْلَةٍ كَانَ فِي مَحَلِّ رَفْعٍ، وَيُعْرَبُ كُلُّ جُزْءٍ دَاخِلَهُ بِحَسَبِ عَامِلِهِ.'),
    ('Мединский курс (Том 3)', '11', 'مُطَابَقَةُ الْخَبَرِ لِلْمُبْتَدَأِ (согласование хабара с мубтада)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-predicate">الْخَبَرُ</span> يُطَابِقُ <span class="ar-tone-subject">الْمُبْتَدَأَ</span> فِي الْعَدَدِ وَالْجِنْسِ.</span><p class="rule-study-text">Хабар согласуется с мубтада по числу и роду.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Согласование по числу</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَدَدُ</span><span class="rule-table-ru">число</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-table-ru">мубтада</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">хабар</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِفْرَادُ</span><span class="rule-table-ru">единственное число</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُدَرِّسُ وَاقِفٌ.</span><span class="rule-table-ru">Преподаватель стоит.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُدَرِّسُ</span><span class="rule-table-ru">преподаватель</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">وَاقِفٌ</span><span class="rule-table-ru">стоящий</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّثْنِيَةُ</span><span class="rule-table-ru">двойственное число</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطَّالِبَانِ جَالِسَانِ.</span><span class="rule-table-ru">Два студента сидят.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الطَّالِبَانِ</span><span class="rule-table-ru">два студента</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">جَالِسَانِ</span><span class="rule-table-ru">двое сидят</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَمْعُ</span><span class="rule-table-ru">множественное число</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطُّلَّابُ خَارِجُونَ.</span><span class="rule-table-ru">Студенты вышли.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الطُّلَّابُ</span><span class="rule-table-ru">студенты</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَارِجُونَ</span><span class="rule-table-ru">вышедшие</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَمْعُ</span><span class="rule-table-ru">множественное число</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطَّالِبَاتُ مُتَحَجِّبَاتٌ.</span><span class="rule-table-ru">Студентки покрыты хиджабом.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الطَّالِبَاتُ</span><span class="rule-table-ru">студентки</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُتَحَجِّبَاتٌ</span><span class="rule-table-ru">покрытые хиджабом</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Согласование по роду</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجِنْسُ</span><span class="rule-table-ru">род</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-table-ru">мубтада</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">хабар</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّذْكِيرُ</span><span class="rule-table-ru">мужской род</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَامِدٌ مُهَنْدِسٌ.</span><span class="rule-table-ru">Хамид — инженер.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">حَامِدٌ</span><span class="rule-table-ru">Хамид</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُهَنْدِسٌ</span><span class="rule-table-ru">инженер</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّأْنِيثُ</span><span class="rule-table-ru">женский род</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَاطِمَةُ طَبِيبَةٌ.</span><span class="rule-table-ru">Фатима — врач.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فَاطِمَةُ</span><span class="rule-table-ru">Фатима</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">طَبِيبَةٌ</span><span class="rule-table-ru">врач</span></td></tr></tbody></table></div></div></div>', 7, 'rule', 'Хабар согласуется с мубтада в единственном, двойственном и множественном числе, а также в мужском и женском роде.', 'يُطَابِقُ الْخَبَرُ الْمُبْتَدَأَ فِي الْإِفْرَادِ وَالتَّثْنِيَةِ وَالْجَمْعِ، وَفِي التَّذْكِيرِ وَالتَّأْنِيثِ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'الدَّرْسُ الْحَادِي عَشَرَ
الْمُبْتَدَأُ ، والْخَبَرُ
المبتدأُ ، هو : الاسمُ المرفوعُ الَّذي نَتَحَدَّثُ عنه .
الخبرُ ، هو : الاسمُ المرفوعُ الَّذي تَتِمُّ به الفَائِدَةُ .
الأمثلة :
الكتابُ جديدٌ . في هذه الجملة أَرَدْنَا أَنْ نَتَحَدَّث عن الكتاب، إذاً ( الكتابُ ) مبتدأ،
وأَرَدْنَا أَنْ نُكْمِلَ الكلام لِتَتِمَّ الفائدة ، فقلنا : جديدٌ ، إذاً ( جديدٌ ) خبر .
ومِنَ الأمثلةِ : القرآنُ كتابُ اللهِ . أنت طالبٌ . هذا مسجدٌ .
أنواع المبتدأ : المبتدأ نوعان ، هما :
1- اسمٌ صَرِيحٌ ، نحو: اللهُ رَبُّنَا ، محمدٌ رَسُولُنَا، الإسلامُ دِينُنَا، نحن طلابٌ، هُنَّ طالباتٌ .
2- مَصْدَرٌ مُؤَوَّلٌ ، نحو : أَنْ تكتبَ الدرسَ أفضلُ مِنَ اللَّعِبِ ، أي : كتابتُك الدرسَ أفضلُ من اللَّعب . قال تعالى : ﴿ وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى ﴾ .', 43, 44, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'تَعْرِيفُ الْمُبْتَدَأِ ، وتَنِْكيرُهُ : الأصلُ في المبتدأِ أنْ يكونَ معرفةً ، نحو :
اللهُ رَبُّنَا . نحن طُلاَّبٌ . أنا مدرَّسٌ . مِفتاحُ الجنَّةِ الصَّلاَةُ .
* يَأْتِي المبتدأُ نكرةً بشروطٍ ، منها :
1- إذا تَقَـدَّم الخبرُ وهو شبْهُ جملةٍ ( جَارٌّ ومجرورٌ ، أو ظَرْفٌ ) نحو :
لي أَخٌ . في البيتِ ضَيْفٌ ؛ عندنا سيَّارةٌ . فوقَ الشَّجرةِ عُصْفُورٌ .
2- إذا كان المبتدأُ اسمَ استفهامٍ ، نحو : ما بك ؟ مَنْ مريضٌ ؟ كَمْ طالباً في الفصل ؟.
فأسماء الاستفهام ( مَا ، ومَنْ ، وكَمْ ) في محل رفع مبتدأ .
و ( بِكَ ، ومريضٌ ، وفي الفصل ) خبر . ومعلومٌ أنّ أسماء الاستفهام نَكِرَاتٌ .', 44, 44, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11' and sort_order = 2;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'التَّرْتِيبُ بين المبتدأِ والخبرِ : الأصلُ أن يَتَقَدَّمَ المبتدأُ على الخبرِ ، نحو :
أنت مدرَّسٌ . القرآنُ كتابُ اللهِ .             أَنْ تحفظَ القرآنَ خيرٌ لك .
مبتدأ  خبر     مبتدأ     خبر                    مبتدأ            خبر
وُجُوبُ تَقْدِيمِ المبتدأِ : يجبُ تقديمُ المبتدأِ بشروطٍ ، منها :
1- إذا كانَ المبتدأ اسم استفهام ( أسماء الاستفهام لها حَقُّ الصَّدَارَةِ ) نحو :
ما بك ؟ مَنْ مريضٌ ؟ كمْ كتاباً عندك ؟
2- إذا كان المبتدأ ، والخبر معرفتين ، نحو : الكتابُ صديقي . رَبُّنَا خَالِقُنَا .
3- إذا كان الخبر جملة فعليَّة ، نحو : الطالبُ يكتُبُ ، فاطمةُ خرجتْ .
وجوُب تقديمِ الخبرِ : يجب تقديمُ الخبرِ بشروط ، منها :
1- إذا كان الخبر اسم استفهام ، نحو : ما اسمُكَ ؟ كيف حالك ؟ من المريضُ ؟
* وقع اسم الاستفهام هنا خبراً ؛ لأنه نكرة ، وما بعده معرفة  ، وحق المبتدأ أن يكون معرفة .
2- إذا كان الخبر شبه جملة والمبتدأ نكرة ، نحو : لديَّ سيَّارةٌ ، في البيتِ ضيفٌ ،
قال تعالى : ﴿ وَلَدَيْنَا مَزِيدٌ ﴾ وقال تعالى : ﴿ وَعَلَى أَبْصَارِهِمْ غِشَاوَةٌ ﴾ .
جَوَازُ تقديمِ الخبرِ : يجوزُ تقديمُ الخبرِ بشروط ، منها :
1- إذا لم يحصلْ بتقديمه لَبْسٌ وإِشْكَالٌ ، نحو : عجيبٌ كلامُه . قَائِمٌ عَمرٌو . قُدَّمَ الخبر جوازاً لعدمِ وجودِ لَبْسٍ في تقديمِه .
2-إذا كان الخبر شبه جملة والمبتدأ معرفة ، نحو : عندنا زيدٌ . في صدورنا كتابُ الله .
3- إذا كان الخبر اسم فاعل مسبوق باستفهام ، نحو : أمدرَّس أنتَ ؟  أمُسَافِرٌ أخوك ؟ .', 44, 45, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11' and sort_order = 3;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'حَذْفُ المبتدأِ ، أو الخبرِ: يجوزُ حذفُ المبتدأ إذا عُلِمَ ، كَأَنْ تقولَ ( بِخَيْرٍ ) لِمَنْ قال لك: كيف حالك؟ والتقدير: أنا بخير ؛ وتقول لِمَنْ سألك عن اسمك (حامدٌ) أي: اسمي حامدٌ.
ويجوز حذف الخبر إذا عُلِمَ ، كَأَنْ تقولَ ( كِتَابانِ ) لِمَنْ قال لك : كم كتاباً عندك ؟ والتقدير : عندي كتابان ؛ وتقول ( أنا ) لِمَنْ قال : مَنْ فَاهِمٌ ، أي : أنا فاهِمٌ .
ويجوزُ حذفُ المبتدأِ ، والخبرِ معاً إذا عُلِمَا ، كأنْ تقولَ ( نَعَمْ ) لِمَنْ سألك: أطالبٌ أنت؟  والتقدير : نعم . أنا طالبٌ .', 46, 46, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11' and sort_order = 4;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'أنواعُ الخبرِ : الخبرُ ثلاثةُ أنواعٍ ، هي :
1- مُفْرَدٌ ، نحو : الطالبٌ مجتهدٌ ، الطالبانِ مجتهدانِ ، الطلابُ مجتهدون ،           الطالبات مجتهداتٌ . المقصود بالخبر المفرد : ما ليس جملة ، ولا شِبه جُملة .
2- جُمْلَةٌ ، والجملةُ نوعان ، هما :
( أ ) جملةٌ اسميَّةٌ ، نحو : المديرُ ما اسمُه ، النَّيَّةُ مَحَلُّها القَلْبُ ، الطالبُ كتابُه جديدٌ .
(ب) جملةٌ فعليَّةٌ ، نحو : اللهُ خَلَقَنَا ، المدرَّسان خَرَجَا ، الطلابُ يكتبون دروسهم .
* يُشترط في الخبر الجملة أن يشتمل على ضمير يعود إلى المبتدأ ، كما في الأمثلة السابقة .
تَأَمَّل ذلك جيَّداً .
3- شِبْهُ جملةٍ ، وشبهُ الجملة نوعان ، هما :
( أ ) جَارٌّ ومَجْرُورٌ ، نحو : الحمدُ للهِ ، الطلابٌ في المطعمِ .
(ب) ظَرْفٌ ، نحو : الجنَّةُ تحت ظِلاَلِ السُّيُوفِ ، المدرَّسُ عند المدير .', 46, 46, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '11' and sort_order = 5;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'الإعراب :
* الطالبُ مجتهدٌ .
الطالبُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .
مجتهدٌ : خبر مرفوع وعلامة رفعه الضمة الظاهرة .
* المديرُ ما اسمُه .
المديرُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .
ما : اسم استفهام مبني على السكون في محل رفع خبر مقدّم .
اسمُه : مبتدأ مؤخَّر مرفوع وعلامة رفعه الضمة الظاهرة ، وهو مضاف ، والضمير :
في محل جر مضاف إليه .
والجملة الاسمية من الخبر والمبتدأ ( ما اسمه ) في محل رفع خبر للمبتدأ الأوَّل ( المدير ) .
* الله خلقنا .
اللهُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .
خَلَقَنَا : فعل ماضٍ مبني على الفتح ، والضمير ( نا ) في محل نصب مفعول به، والفاعل ضمير مستتر تقديره ( هو ) والجملة الفعلية ( خلقنا ) في محل رفع خبر المبتدأ .
* الحمدُ لِلَّهِ .
الحمدُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .
لله : اللام حرف جر مبني على الكسر، ولفظ الجلالة : اسم مجرور باللام وعلامة
جره الكسرة الظاهرة ، والجار والمجرور في محل رفع خبر المبتدأ .
* المدرسُ عندَ المديرِ .
المدرسُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .
عندَ : ظرف مكان منصوب وعلامة نصبه الفتحة الظاهرة ، وهو مضاف .
المديرِ : مضاف إليه مجرور وعلامة جره الكسرة الظاهرة ، والظرف مع مجروره في
